showHottest("Anadolu");
await sleep(300);
assert(info() === "En sıcak: Gaziantep (21°C)", "'Anadolu' için en sıcak şehir Gaziantep (21°C) olmalı.");
showHottest("Mars");
await sleep(300);
assert(info() === "Şehir bulunamadı", "Şehir gelmeyince #info 'Şehir bulunamadı' olmalı.");
