const list = document.querySelector("#tasks");
const count = document.querySelector("#count");

function renderTasks(tasks) {
  list.innerHTML = "";
  for (const task of tasks) {
    const li = document.createElement("li");
    li.textContent = task.baslik;
    if (task.bitti) li.classList.add("done");
    list.append(li);
  }
  const left = tasks.filter((t) => !t.bitti).length;
  count.textContent = `${left} görev kaldı`;
}

async function loadTasks() {
  count.textContent = "Yükleniyor...";
  const res = await fetch("/demo-api/gorevler");
  if (!res.ok) {
    count.textContent = "Görevler alınamadı.";
    return;
  }
  const tasks = await res.json();
  renderTasks(tasks);
}

loadTasks();

check.js:
await sleep(350);
const items = $$("#tasks li");
assert(items.length === 4, "#tasks içinde 4 görev olmalı.");
assert(items[1].textContent.trim() === "Fizik tekrarı", "Her <li> görevin başlığını göstermeli.");
assert(items[0].classList.contains("done") && !items[1].classList.contains("done") && items[3].classList.contains("done"), "Bitmiş görevlerin <li>'sinde done sınıfı olmalı, diğerlerinde olmamalı.");
assert($("#count").textContent.trim() === "2 görev kaldı", "#count '2 görev kaldı' olmalı.");
renderTasks([{ id: 7, baslik: "Deneme", bitti: false }, { id: 8, baslik: "Proje", bitti: false }, { id: 9, baslik: "Tekrar", bitti: false }]);
assert($$("#tasks li").length === 3, "renderTasks listeyi önce temizlemeli.");
assert($("#count").textContent.trim() === "3 görev kaldı", "Kalan sayısı verilen görevlerden hesaplanmalı.");

