project_task.solution:
let questions = [];
const questionEl = document.querySelector("#question");
const options = document.querySelector("#options");

function showQuestion(index) {
  const q = questions[index];
  questionEl.textContent = `Soru ${index + 1}: ${q.soru}`;
  options.innerHTML = "";
  q.secenekler.forEach((text) => {
    const btn = document.createElement("button");
    btn.textContent = text;
    options.append(btn);
  });
}

async function loadQuestions() {
  const res = await fetch("/demo-api/sorular");
  if (!res.ok) {
    questionEl.textContent = "Sorular yüklenemedi.";
    return;
  }
  questions = await res.json();
  showQuestion(0);
}

loadQuestions();

check.js:
await sleep(350);
assert(Array.isArray(questions) && questions.length === 5, "Gelen 5 soru questions değişkenine konmalı.");
assert($("#question").textContent.trim() === "Soru 1: Ay, hangi gezegenin uydusudur?", "#question 'Soru 1: Ay, hangi gezegenin uydusudur?' olmalı.");
const texts = () => $$("#options button").map((b) => b.textContent.trim()).join(",");
assert(texts() === "Mars,Dünya,Jüpiter", "#options içinde Mars, Dünya, Jüpiter düğmeleri olmalı.");
showQuestion(3);
assert($("#question").textContent.trim() === "Soru 4: Güneş'e en yakın gezegen hangisidir?", "showQuestion(3) dördüncü soruyu göstermeli.");
assert(texts() === "Venüs,Dünya,Merkür", "Yeni soruda eski düğmeler temizlenmeli, yenileri eklenmeli.");
